INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (11, 'U5 听力·短文 Three Rules of First Aid', '选择性必修二 U5 · passage', 2, 'Here are three simple rules to remember when you give first aid.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit) VALUES (11, 'Write a Safety Guide: First-Aid Steps for an Emergency(写一份急救步骤说明)', 'How to Give First Aid for a Burn', '假设你是学校急救社团的成员,社团要制作一本《校园急救手册》。请用英语写一段约100词的说明文,说明烧伤(或烫伤)的急救步骤。内容包括:① 先做什么、为什么(用凉水冲);② 接下来的两三个步骤(擦干、宽松包扎等);③ 一条不该做的事(如抹油);④ 什么情况下要立即送医院。注意:用 first / next / then / finally 等顺序词,使过去完成时/被动语态等在合适处自然出现。', 'Suppose you are a member of your school''s first-aid club, which is making a Campus First-Aid Manual. Write a guide of about 100 words explaining the steps of first aid for a burn. Include: 1) what to do first and why (cool running water); 2) the next two or three steps (dry it, cover it loosely, etc.); 3) one thing you should NOT do (e.g. put oil on it); 4) when to take the victim to hospital at once. Use ordering words such as first, next, then and finally.', '["第一步与原因(First, place the burn under cool running water… because it stops the burning process）","中间步骤(Next, dry the area gently. / Then cover it loosely with a clean cloth.）","一条禁忌(Never put oil on a burn, as it keeps the heat in.）","送医时机 + 顺序词连贯(Finally, if the burn is serious, take the victim to hospital at once.）"]'::jsonb, 70, 100, 'Knowing how to treat a burn can make a big difference in an emergency. First, place the burnt area under cool running water for about ten minutes, because this stops the burning process and reduces the pain. Next, dry the area gently with a clean cloth. Then cover the burn loosely with another clean cloth to keep it safe. Never put oil or butter on a burn, as this keeps the heat in the wound and may cause infection. If clothes are stuck to the skin, do not pull them off. Finally, if the burn is a serious one, take the victim to hospital at once.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["First, place the burnt area under cool running water, because this stops the burning process.","Then cover the burn loosely with a clean cloth to keep it safe.","Never put oil or butter on a burn, as this keeps the heat in the wound.","Finally, if the burn is a serious one, take the victim to hospital at once."]'::jsonb, '[{"wrong":"Put the burn under water can stop the pain.","correct":"Putting the burn under water can stop the pain.","note":"句首作主语用动名词 Putting,不用动词原形。"},{"wrong":"When I arrived, the nurse already cleaned the wound.","correct":"When I arrived, the nurse had already cleaned the wound.","note":"''我到达''前已发生,过去的过去用过去完成时 had cleaned。"},{"wrong":"The wound was clean before she covered it.","correct":"The wound had been cleaned before she covered it.","note":"伤口被清洗(被动)且在更早,用过去完成被动 had been cleaned。"}]'::jsonb, '【急救步骤说明文结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content) VALUES (11, 'elective2', 'U5', '{"title":"过去完成时及其被动语态(had done / had been done)速查","intro":"过去完成时表示「过去的过去」:在某个过去时间点之前已经完成或已持续的动作。构成 had + 过去分词(主动 had done;被动 had been done)。判断口诀:两个过去动作,先发生的那个用过去完成。","table":{"headers":["形式","用法 / 例句"],"rows":[["had done(主动)","过去某点前已完成:When the doctor arrived, the man had stopped breathing."],["had been done(被动)","主语承受动作:The wound had been cleaned before she bandaged it."],["对照一般过去","先发生→had done;后发生→did:By the time help came, he had given first aid."],["倒装强调","No sooner had…than… / Hardly had…when…:刚一……就……"]]},"specialRules":[{"rule":"两个过去动作,先发生的用过去完成,后发生的用一般过去","mark":"She had cleaned the wound before she covered it."},{"rule":"被动语态:had + been + 过去分词","mark":"The victim had already been taken to hospital."},{"rule":"常见时间标志:by + 过去时间 / by the time / before / after / already","mark":"By 2010, she had worked there for ten years."},{"rule":"No sooner / Hardly 置于句首要部分倒装","mark":"No sooner had he swallowed it than he began to choke."}],"why":["过去完成时是为了把两个过去动作分出先后:用 had done 把更早的动作''推''到更远的过去,听者一下就知道哪件事先发生。被动时主语不是动作的执行者,就把 had done 变成 had been done。"],"gaokaoPoints":["by the time / before / after 引导的句子里时态前后呼应(过去完成 vs 一般过去),语法填空与改错高频。","No sooner had…than… 和 Hardly had…when… 的倒装与连词搭配(than 配 No sooner,when 配 Hardly),不可混用。","被动判断:看主语是否承受动作,是则用 had been done。"],"examVsReal":[{"exam":"When I arrived, he had already left.（考试严格区分先后）","real":"When I arrived, he already left.（口语有时也用一般过去）","note":"考试看到''过去的过去''必须用过去完成;日常口语里如先后很清楚,母语者偶尔用一般过去"},{"exam":"No sooner had she sat down than the phone rang.（书面/考试倒装）","real":"She had just sat down when the phone rang.（口语更常这样说）","note":"倒装结构正式、考试爱考;口语里人们更爱用 just…when 表达同样意思"}]}'::jsonb);
